with gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 1 hour then 1 else 0 end as is_new_burst from device_readings), sessionized as (select *, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from gaps) select device_code, round(avg(status_bits), 2) as avg_status_bits, max(reading_ts) as last_reading_ts, count(distinct firmware) as distinct_firmwares, stddev_samp(temp_c) as temp_c_stddev, stddev_samp(status_bits) as status_bits_stddev from sessionized group by 1;
